const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const N = data[0];
const L = data.slice(1, 1 + N);

let circumference = 0;
for (let i = 0; i < N; i++) {
  circumference += L[i];
}

if (circumference % 2 !== 0) {
  process.stdout.write('N\n');
  process.exit(0);
}

const target = circumference / 2;

const pos = new Array(N);
let cur = 0;
for (let i = 0; i < N; i++) {
  pos[i] = cur;
  cur += L[i];
}

const doubled = new Array(2 * N);
for (let i = 0; i < N; i++) {
  doubled[i] = pos[i];
  doubled[i + N] = pos[i] + circumference;
}

function lowerBound(arr, value, left, right) {
  while (left < right) {
    const mid = (left + right) >> 1;
    if (arr[mid] < value) left = mid + 1;
    else right = mid;
  }
  return left;
}

let orderedPairs = 0;

for (let i = 0; i < N; i++) {
  const value = pos[i] + target;
  const idx = lowerBound(doubled, value, 0, 2 * N);
  if (idx < 2 * N && doubled[idx] === value) {
    orderedPairs++;
  }
}

process.stdout.write(orderedPairs >= 4 ? 'S\n' : 'N\n');
